// This file is generated by AI.

// 角色列表: 管理 GSOV 模型 + 参考音频组合。
//
// 顶部为搜索 / 选择 / 新建; 列表按响应式网格排布 (窗口足够宽时两列)。
// 参考音频的增删改在「选择角色」对话框内完成, 列表本身只展示与编辑角色元信息。

import { Button, Dropdown, Field, Input, Option, Textarea } from '@fluentui/react-components';
import { AddRegular, ArrowDownloadRegular, DeleteRegular, StarFilled, StarRegular } from '@fluentui/react-icons';
import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { useEffect, useMemo, useState } from 'react';

import type { Character, ModelCandidate } from '../commands/voice';
import { voiceExportCharacter } from '../commands/voice';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { RolePickerDialog } from './RolePickerDialog';
import { LANGUAGE_LABELS } from './types';

export function RoleListPanel({ onOpenHelp }: { onOpenHelp: () => void }) {
  const characters = useAppStore((state) => state.voiceCharacters);
  useAppStore((state) => state.voiceTick);
  const voiceStatus = useAppStore((state) => state.voiceStatus);
  const [query, setQuery] = useState('');
  const [pickerOpen, setPickerOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [models, setModels] = useState<ModelCandidate[]>([]);
  const [switching, setSwitching] = useState(false);

  useEffect(() => {
    voiceController.primeReferencePaths().catch(() => {});
  }, [characters.length]);

  // 扫描整合包内的 v4 权重, 为角色的模型下拉提供候选
  useEffect(() => {
    void voiceController.listModels().then(setModels);
  }, [characters.length]);

  const enabled = useMemo(
    () => characters.filter((character) => character.enabled && matchesQuery(character, query)),
    [characters, query]
  );

  const create = async () => {
    setError(null);
    try {
      const created = await voiceController.createCharacter(`新角色 ${characters.length + 1}`, [], '');
      setPickerOpen(false);
      // 立刻展开以备填写
      setQuery('');
      void created;
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  const exportCharacter = async (character: Character) => {
    const destination = await saveDialog({
      defaultPath: `${character.name}.zip`,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    await voiceExportCharacter(character.id, destination);
  };

  return (
    <div className="character-panel">
      <div className="character-toolbar">
        <Input
          className="character-search"
          placeholder="搜索角色名或别名…"
          value={query}
          onChange={(_, data) => setQuery(data.value)}
        />
        <Button appearance="secondary" onClick={() => setPickerOpen(true)}>
          选择角色
        </Button>
        <Button appearance="primary" icon={<AddRegular />} onClick={() => void create()}>
          新建角色
        </Button>
        <span className="voice-actions-spacer" />
        <Button appearance="subtle" onClick={onOpenHelp}>
          帮助
        </Button>
      </div>

      {error && <p className="voice-error">{error}</p>}

      <div className="character-list">
        {characters.length === 0 && (
          <p className="voice-dialog-empty">还没有角色。先「新建角色」或导入一份角色配置。</p>
        )}
        {characters.length > 0 && enabled.length === 0 && (
          <p className="voice-dialog-empty">没有已启用的角色。请在「选择角色」中勾选需要参与配音的角色。</p>
        )}
        {enabled.map((character) => (
          <CharacterCard
            key={character.id}
            character={character}
            models={models}
            canSwitchModel={voiceStatus === 'ready'}
            switching={switching}
            onSwitchModel={async (next) => {
              setSwitching(true);
              setError(null);
              try {
                await voiceController.switchModel(next.model?.gptWeights ?? null, next.model?.sovitsWeights ?? null);
                await voiceController.persistCharacter(next);
              } catch (caught) {
                setError(caught instanceof Error ? caught.message : String(caught));
              } finally {
                setSwitching(false);
              }
            }}
            onExport={() => void exportCharacter(character)}
            onError={setError}
          />
        ))}
      </div>

      <RolePickerDialog open={pickerOpen} onClose={() => setPickerOpen(false)} onError={setError} />
    </div>
  );
}

function CharacterCard({
  character,
  models,
  canSwitchModel,
  switching,
  onSwitchModel,
  onExport,
  onError,
}: {
  character: Character;
  models: ModelCandidate[];
  canSwitchModel: boolean;
  switching: boolean;
  onSwitchModel: (character: Character) => Promise<void>;
  onExport: () => void;
  onError: (error: string | null) => void;
}) {
  const [draft, setDraft] = useState(character);

  useEffect(() => {
    setDraft(character);
  }, [character.updatedAt]);

  const commit = async (patch: Partial<Character>) => {
    const next = { ...draft, ...patch };
    setDraft(next);
    try {
      await voiceController.persistCharacter(next);
      onError(null);
    } catch (caught) {
      onError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  return (
    <div className="character-card">
      <div className="character-head">
        <Input
          className="character-name"
          value={draft.name}
          onChange={(_, data) => setDraft({ ...draft, name: data.value })}
          onBlur={() => void commit({ name: draft.name })}
        />
        <span className="character-id" title="角色 ID（用于 game/vocal 下的目录名）">
          {draft.id}
        </span>
        <Button
          size="small"
          appearance="subtle"
          title={draft.starred ? '取消星标' : '星标（在选择列表中靠前）'}
          icon={draft.starred ? <StarFilled /> : <StarRegular />}
          onClick={() => void commit({ starred: !draft.starred })}
        />
        <Button
          size="small"
          appearance="subtle"
          title="导出角色（不含模型选择）"
          icon={<ArrowDownloadRegular />}
          onClick={onExport}
        />
      </div>

      <Field label="GSOV 模型（本地记录，不参与导出）">
        {models.length > 0 && (
          <Dropdown
            className="character-model-pick"
            placeholder="从整合包扫描到的模型中选择"
            selectedOptions={[]}
            value={modelSummary(draft, models)}
            onOptionSelect={(_, data) => {
              const picked = models.find((item) => item.gptWeights === data.optionValue);
              if (picked) {
                void commit({
                  model: { gptWeights: picked.gptWeights, sovitsWeights: picked.sovitsWeights },
                });
              }
            }}
          >
            {models.map((item) => (
              <Option key={item.gptWeights} value={item.gptWeights} text={item.name}>
                {item.name}
              </Option>
            ))}
          </Dropdown>
        )}
        <div className="character-model">
          <Input
            placeholder="GPT 权重路径（如 GPT_weights_v4/xxx-e15.ckpt）"
            value={draft.model?.gptWeights ?? ''}
            onChange={(_, data) => setDraft({ ...draft, model: { ...(draft.model ?? {}), gptWeights: data.value } })}
            onBlur={() => void commit({ model: draft.model })}
          />
          <Input
            placeholder="SoVITS 权重路径（如 SoVITS_weights_v4/xxx.pth）"
            value={draft.model?.sovitsWeights ?? ''}
            onChange={(_, data) => setDraft({ ...draft, model: { ...(draft.model ?? {}), sovitsWeights: data.value } })}
            onBlur={() => void commit({ model: draft.model })}
          />
        </div>
        <div className="character-model-actions">
          <span className="character-model-note">
            {canSwitchModel
              ? '切换服务端权重会重载模型，通常无需手动操作（队列会按角色分组连续执行）'
              : 'GSOV 就绪后可切换服务端权重'}
          </span>
          <Button
            size="small"
            appearance="secondary"
            disabled={!canSwitchModel || switching || (!draft.model?.gptWeights && !draft.model?.sovitsWeights)}
            onClick={() => void onSwitchModel(draft)}
          >
            {switching ? '切换中…' : '切换到该模型'}
          </Button>
        </div>
      </Field>

      <Field label="默认语言">
        <Dropdown
          selectedOptions={[draft.language]}
          value={LANGUAGE_LABELS[draft.language] ?? draft.language}
          onOptionSelect={(_, data) => void commit({ language: data.optionValue ?? 'auto' })}
        >
          {Object.entries(LANGUAGE_LABELS).map(([code, label]) => (
            <Option key={code} value={code} text={label}>
              {label}
            </Option>
          ))}
        </Dropdown>
      </Field>

      <Field label="别名（参与场景对话者自动匹配，逗号分隔）">
        <Input
          value={draft.aliases.join(', ')}
          onChange={(_, data) =>
            setDraft({
              ...draft,
              aliases: data.value
                .split(',')
                .map((item) => item.trim())
                .filter(Boolean),
            })
          }
          onBlur={() => void commit({ aliases: draft.aliases })}
        />
      </Field>

      <Field label="描述">
        <Textarea
          className="character-description"
          resize="vertical"
          value={draft.description}
          onChange={(_, data) => setDraft({ ...draft, description: data.value })}
          onBlur={() => void commit({ description: draft.description })}
        />
      </Field>

      <div className="character-references">
        <span className="voice-label">参考音频（{draft.references.length}）</span>
        {draft.references.length === 0 ? (
          <p className="voice-dialog-empty">暂无参考音频，请在「选择角色」中添加。</p>
        ) : (
          draft.references.map((reference) => (
            <div key={reference.hash} className="character-reference">
              <span className="reference-text">{reference.text || '（未填写）'}</span>
              <span className="reference-meta">
                {LANGUAGE_LABELS[reference.language] ?? reference.language} · {reference.duration.toFixed(2)}s
              </span>
            </div>
          ))
        )}
      </div>

      <div className="character-actions">
        <Button
          size="small"
          appearance="subtle"
          icon={<DeleteRegular />}
          onClick={() => {
            void voiceController
              .deleteCharacter(character.id)
              .catch((caught: unknown) => onError(caught instanceof Error ? caught.message : String(caught)));
          }}
        >
          删除角色
        </Button>
      </div>
    </div>
  );
}

function matchesQuery(character: Character, query: string): boolean {
  if (!query.trim()) return true;
  const needle = query.trim().toLowerCase();
  return (
    character.name.toLowerCase().includes(needle) ||
    character.id.toLowerCase().includes(needle) ||
    character.aliases.some((alias) => alias.toLowerCase().includes(needle))
  );
}

/** 当前模型选择的可读摘要 */
function modelSummary(character: Character, models: ModelCandidate[]): string {
  const gpt = character.model?.gptWeights;
  if (!gpt) return '未指定模型';
  const matched = models.find((item) => item.gptWeights === gpt);
  return matched ? matched.name : gpt;
}
